INSERT INTO questions (id, content, difficulty, sub_category_id) VALUES
('b0000000-0000-0000-0011-000000000000', 'Redis란 무엇이며 어떤 특징을 가지고 있나요?', 'EASY', 'b0000000-0000-0000-0000-000000000011'),
('b0000000-0000-0000-0011-000000000001', 'Redis는 싱글 스레드로 동작하는데, 성능은 왜 여전히 뛰어난가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000011'),
('b0000000-0000-0000-0011-000000000002', 'Redis는 어떤 자료 구조들을 지원하나요?', 'EASY', 'b0000000-0000-0000-0000-000000000011'),
('b0000000-0000-0000-0011-000000000003', '캐시로서 Redis를 사용하는 경우의 장단점은 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000011'),
('b0000000-0000-0000-0011-000000000004', 'Redis에서 지속성(persistence)을 제공하는 방법은 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000011'),
('b0000000-0000-0000-0011-000000000005', 'RDB(snapshot)와 AOF(Append Only File)의 차이는 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000011'),
('b0000000-0000-0000-0011-000000000006', 'Redis 복제(replication)는 어떻게 동작하나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000011'),
('b0000000-0000-0000-0011-000000000007', 'Redis의 마스터-슬레이브 구조에서 슬레이브는 어떤 역할을 하나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000011'),
('b0000000-0000-0000-0011-000000000008', 'Redis Sentinel의 역할은 무엇인가요?', 'HARD',   'b0000000-0000-0000-0000-000000000011'),
('b0000000-0000-0000-0011-000000000009', 'Redis 클러스터(Cluster)란 무엇이며, 어떻게 고가용성을 구현하나요?', 'HARD',   'b0000000-0000-0000-0000-000000000011'),
('b0000000-0000-0000-0011-000000000010', 'Redis 클러스터링과 복제의 차이는 무엇인가요?', 'HARD',   'b0000000-0000-0000-0000-000000000011'),
('b0000000-0000-0000-0011-000000000011', 'Redis에서 샤딩(sharding)이란 무엇이고 수동으로 구현할 수 있나요?', 'HARD', 'b0000000-0000-0000-0000-000000000011'),
('b0000000-0000-0000-0011-000000000012', '메모리 제한에 도달했을 때 Redis의 eviction 정책은 무엇인가요?', 'MEDIUM','b0000000-0000-0000-0000-000000000011'),
('b0000000-0000-0000-0011-000000000013', 'LRU(Least Recently Used) 정책은 어떻게 동작하나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000011'),
('b0000000-0000-0000-0011-000000000014', 'Redis에서 파이프라이닝(Pipelining)이란 무엇이며 왜 사용하나요?', 'MEDIUM','b0000000-0000-0000-0000-000000000011'),
('b0000000-0000-0000-0011-000000000015', 'Redis에서 Pub/Sub 기능은 무엇이고 어디에 활용할 수 있나요?', 'MEDIUM','b0000000-0000-0000-0000-000000000011'),
('b0000000-0000-0000-0011-000000000016', '스크립팅(Scripting)을 위해 Redis는 어떤 기능을 제공하나요? (예: Lua 스크립트)', 'HARD','b0000000-0000-0000-0000-000000000011'),
('b0000000-0000-0000-0011-000000000017', 'Redis와 Memcached의 차이점을 간략히 설명해 보세요.', 'MEDIUM','b0000000-0000-0000-0000-000000000011'),
('b0000000-0000-0000-0011-000000000018', 'Redis를 세션 저장소로 사용하면 어떤 이점이 있나요?', 'EASY',  'b0000000-0000-0000-0000-000000000011'),
('b0000000-0000-0000-0011-000000000019', 'Redis 보안 설정이나 인증 기법은 무엇이 있나요?', 'HARD',   'b0000000-0000-0000-0000-000000000011'),
('b0000000-0000-0000-0011-000000000020', '메모리 사용량 최적화를 위해 Redis에서 할 수 있는 설정은?', 'HARD', 'b0000000-0000-0000-0000-000000000011'),
('b0000000-0000-0000-0011-000000000021', '데이터 일관성 측면에서 Redis를 사용할 때 주의해야 할 점은?', 'HARD','b0000000-0000-0000-0000-000000000011'),
('b0000000-0000-0000-0011-000000000022', 'Redis의 싱글 스레드 구조는 성능에 어떤 영향을 주나요?', 'MEDIUM','b0000000-0000-0000-0000-000000000011'),
('b0000000-0000-0000-0011-000000000023', 'Redis의 거래(Transaction)란 무엇이고 어떻게 실행되나요?', 'MEDIUM','b0000000-0000-0000-0000-000000000011'),
('b0000000-0000-0000-0011-000000000024', 'Redis 트랜잭션에서 DISCARD를 호출하면 어떤 일이 발생하나요?', 'MEDIUM','b0000000-0000-0000-0000-000000000011'),
('b0000000-0000-0000-0011-000000000025', 'Redis에서 Atomic 연산이란 무엇인지 예를 들어 설명하세요.', 'MEDIUM','b0000000-0000-0000-0000-000000000011'),
('b0000000-0000-0000-0011-000000000026', 'Redis Persistence 방법에는 무엇이 있고, 차이점은?', 'MEDIUM','b0000000-0000-0000-0000-000000000011')
